-- 020 (2026-10-18): national expansion of the public expert-resources directory (table keeps its name texas_resources).
-- Adds state + covers columns; Texas rows stay. Generated by tools/experts/national.py. Rollback: 020_expert_directory_down.sql
begin;
alter table public.texas_resources add column if not exists state text not null default 'Texas', add column if not exists covers text[] not null default '{}';
update public.texas_resources set covers = array['Texas'] where state = 'Texas' and covers = '{}';
on conflict (slug) do update set name=excluded.name,kind=excluded.kind,specialty=excluded.specialty,region=excluded.region,state=excluded.state,covers=excluded.covers,contact=excluded.contact,contact_url=excluded.contact_url,availability=excluded.availability,source_url=excluded.source_url,last_verified=excluded.last_verified,sort=excluded.sort,updated_at=now();
commit;
